import { describe, expect, it } from 'vitest';

import { findSdkPage, renderSdkTarget } from '../src/sdk/findSdkPage.js';
import type { SdkReference } from '../src/sdk/types.js';

// Pages without target metadata exercise the slug/title heuristic fallback.
const reference: SdkReference = {
  pages: [
    { slug: 'classes/Client', title: 'Client', content: 'class page' },
    { slug: 'sdk/interfaces/Options', title: 'Options', content: 'interface page' },
  ],
  groups: [],
};

describe('findSdkPage heuristic fallback', () => {
  it('matches by kind directory in the slug', () => {
    expect(findSdkPage(reference, { kind: 'class', name: 'Client' })?.slug).toBe('classes/Client');
    expect(findSdkPage(reference, { kind: 'interface', name: 'Options' })?.slug).toBe(
      'sdk/interfaces/Options'
    );
  });

  it('does not match a same-named symbol of a different kind', () => {
    expect(findSdkPage(reference, { kind: 'interface', name: 'Client' })).toBeUndefined();
    expect(() => renderSdkTarget(reference, { kind: 'interface', name: 'Client' })).toThrow(
      'SDK symbol not found: interface Client'
    );
  });

  it('prefers exact target metadata over the heuristic', () => {
    const withTargets: SdkReference = {
      pages: [
        {
          slug: 'other/location',
          title: 'Client',
          content: 'tagged page',
          target: { kind: 'class', name: 'Client' },
        },
        ...reference.pages,
      ],
      groups: [],
    };
    expect(findSdkPage(withTargets, { kind: 'class', name: 'Client' })?.slug).toBe(
      'other/location'
    );
  });

  it('does not fall back to the heuristic for an explicit namespace or a targeted page', () => {
    const targeted: SdkReference = {
      pages: [
        {
          slug: 'other/Client/Do',
          title: 'Client.Do',
          content: '',
          target: { kind: 'method', name: 'Do', parent: 'Client', namespace: 'other' },
        },
        {
          slug: 'classes/Legacy',
          title: 'Legacy',
          content: '',
          target: { kind: 'class', name: 'Legacy' },
        },
        {
          slug: 'classes/Auth.Client/login',
          title: 'Auth.Client.login',
          content: '',
          target: { kind: 'method', name: 'login', parent: 'Client' },
        },
      ],
      groups: [],
    };
    expect(
      findSdkPage(targeted, { kind: 'method', name: 'Do', parent: 'Client', namespace: 'legacy' })
    ).toBeUndefined();
    expect(findSdkPage(targeted, { kind: 'interface', name: 'Legacy' })).toBeUndefined();
    expect(
      findSdkPage(targeted, { kind: 'method', name: 'login', parent: 'Auth.Client' })?.slug
    ).toBe('classes/Auth.Client/login');
    expect(
      findSdkPage(targeted, { kind: 'property', name: 'login', parent: 'Auth.Client' })
    ).toBeUndefined();
  });

  it('keeps the first match when duplicate targets carry no namespace', () => {
    const duplicates: SdkReference = {
      pages: [
        {
          slug: 'a/Client',
          title: 'Client',
          content: '',
          target: { kind: 'class', name: 'Client' },
        },
        {
          slug: 'b/Client',
          title: 'Client',
          content: '',
          target: { kind: 'class', name: 'Client' },
        },
      ],
      groups: [],
    };
    expect(findSdkPage(duplicates, { kind: 'class', name: 'Client' })?.slug).toBe('a/Client');
  });

  it('applies a requested namespace to the symbol or its parent', () => {
    const namespaced: SdkReference = {
      pages: [
        {
          slug: 'legacy/Client',
          title: 'Client',
          content: '',
          target: { kind: 'type', name: 'Client', namespace: 'legacy' },
        },
        {
          slug: 'legacy/Client/Close',
          title: 'Client.Close',
          content: '',
          target: { kind: 'method', name: 'Close', parent: 'Client', namespace: 'legacy' },
        },
        {
          slug: 'x/legacy/Client',
          title: 'Client',
          content: '',
          target: { kind: 'type', name: 'Client', namespace: 'x.legacy' },
        },
      ],
      groups: [],
    };
    expect(
      findSdkPage(namespaced, { kind: 'type', name: 'Client', namespace: 'legacy' })?.slug
    ).toBe('legacy/Client');
    expect(
      findSdkPage(namespaced, { kind: 'type', name: 'Client', namespace: 'x.legacy' })?.slug
    ).toBe('x/legacy/Client');
    expect(findSdkPage(namespaced, { kind: 'type', name: 'legacy.Client' })?.slug).toBe(
      'legacy/Client'
    );
    expect(findSdkPage(namespaced, { kind: 'type', name: 'x.legacy.Client' })?.slug).toBe(
      'x/legacy/Client'
    );
    expect(
      findSdkPage(namespaced, {
        kind: 'method',
        name: 'Close',
        parent: 'Client',
        namespace: 'legacy',
      })?.slug
    ).toBe('legacy/Client/Close');
    expect(() => findSdkPage(namespaced, { kind: 'type', name: 'Client' })).toThrow(
      'type Client matches legacy.Client, x.legacy.Client'
    );
  });
});
